const CATEGORY_STRUCTURE = {
  'Income': ['Income'],
  'Food & Dining': ['Dining Out', 'Groceries'],
  'Transportation': ['Gas & Fuel', 'Auto & Transport'],
  'Housing': ['Utilities', 'Home & Garden'],
