  const dayOfMonth = now.getDate();
  const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  const pct = Math.round((dayOfMonth / daysInMonth) * 100);

  // Get budget data
  const budget = await api.getBudgetMonth(currentMonth);

  // Get spending transactions for current month
  const skipPatterns = ['Retirement', 'Investing', 'IRA', '401', 'Self-Directed'];
  let spending = {};

  for (const acc of accounts) {
    if (acc.closed || skipPatterns.some(p => acc.name.includes(p))) continue;
    const txs = await api.getTransactions(acc.id);
    txs.filter(t => t.date?.startsWith(currentMonth) && t.amount < 0).forEach(t => {
      const cat = catMap[t.category] || 'Uncategorized';
      if (!cat.includes('Transfer') && !cat.includes('Credit Card')) {
        if (!spending[cat]) spending[cat] = 0;
        spending[cat] += Math.abs(t.amount) / 100;
      }
    });
  }

  // Budget targets
  const budgets = {
    'Mortgage': 4000, 'Shopping': 2000, 'Auto & Transport': 1350,
    'Utilities': 700, 'Groceries': 800, 'Dining Out': 500,
    'Fitness': 350, 'Healthcare': 200, 'Insurance': 500,
    'Subscriptions': 150, 'Pet Care': 100, 'Home & Garden': 150,
    'Travel': 500, 'Personal Care': 100, 'Gifts & Donations': 200,
    'Gas & Fuel': 50, 'Software & Cloud': 50, 'Taxes & Gov': 100, 'Fees': 50
  };

  console.log(\`📊 FEBRUARY 2026 BUDGET STATUS\`);
  console.log(\`Day \${dayOfMonth} of \${daysInMonth} (\${pct}% through month)\`);
  console.log(\`To Budget: \$\${(budget.toBudget/100).toFixed(0)} ✅\`);
  console.log(\`\\n\`);

  let totalSpent = 0;
  let totalBudget = 0;
  const issues = [];
  const wins = [];

  Object.entries(budgets).forEach(([cat, bgt]) => {
    const spent = spending[cat] || 0;
    totalSpent += spent;
    totalBudget += bgt;
    const pctUsed = Math.round((spent / bgt) * 100);
    const prorated = bgt * (dayOfMonth / daysInMonth);

    if (spent > bgt) {
      issues.push({ cat, spent, bgt, pctUsed });
    } else if (spent > prorated * 1.1 && spent > 100) {
      issues.push({ cat, spent, bgt, pctUsed, warning: true });
    } else if (pctUsed < 30 && spent > 0) {
      wins.push({ cat, spent, bgt, pctUsed });
    }
  });

  // Show issues first
  if (issues.length > 0) {
    console.log('⚠️ WATCH LIST:');
    issues.forEach(i => {
      const icon = i.warning ? '🟡' : '🔴';
      console.log(\`\${icon} \${i.cat}: \$\${i.spent.toFixed(0)}/\$\${i.bgt} (\${i.pctUsed}%)\`);
    });
    console.log('');
  }

  // Summary
  const proratedBudget = totalBudget * (dayOfMonth / daysInMonth);
  const status = totalSpent <= proratedBudget ? '✅ On track' : '⚠️ Ahead of pace';

  console.log(\`💰 TOTAL: \$\${totalSpent.toFixed(0)} / \$\${totalBudget} (\${Math.round(totalSpent/totalBudget*100)}%)\`);
  console.log(\`Prorated target: \$\${proratedBudget.toFixed(0)}\`);
  console.log(\`Status: \${status}\`);

  await api.shutdown();
}
main();
