async function main() {
  await api.init({
    dataDir: '/tmp/actual-data',
    serverURL: 'http://actual-budget:5006',
    password: 'RGR!vwy*hay.vgm0dpg',
  });
  await api.downloadBudget('9b174808-0fe7-4d4d-9b09-7573d3caf074');

  const categories = await api.getCategories();
  const catByName = {};
  categories.forEach(c => { catByName[c.name] = c.id; });

  // New category budgets
  const newBudgets = {
    // Business
    'Business - Software': 100,
    'Business - Equipment': 50,
    'Business - Travel': 100,
    'Business - Services': 100,

    // Home Services
    'Cleaning/Housekeeping': 200,
    'Lawn & Snow': 100,
    'Home Security': 50,

    // Lifestyle
    'Clothing': 200,
    'Entertainment': 200,
    'Alcohol & Bars': 100,
    'Education & Books': 50,

    // Auto split (reallocate from Auto & Transport \$1350)
    'Auto - GV70 Loan': 780,
    'Auto - GV60 Loan': 510,
    'Auto - Maintenance': 50,
    'Auto - Parking': 50,

    // Financial
    'Charitable Donations': 100,
  };

  const months = [];
  for (let year = 2024; year <= 2026; year++) {
    for (let m = 1; m <= 12; m++) {
      months.push(\`\${year}-\${m.toString().padStart(2, '0')}\`);
    }
  }

  console.log('Setting budgets for new categories...\\n');

  let totalNew = 0;
  for (const [cat, amount] of Object.entries(newBudgets)) {
    const catId = catByName[cat];
    if (!catId) {
      console.log('  ⚠️ Not found: ' + cat);
      continue;
    }

    for (const month of months) {
      await api.setBudgetAmount(month, catId, amount * 100);
    }
    console.log('  ✓ ' + cat.padEnd(25) + ' \$' + amount + '/mo');
    totalNew += amount;
  }

  // Zero out the old Auto & Transport since we split it
  const oldAutoId = catByName['Auto & Transport'];
  if (oldAutoId) {
    for (const month of months) {
      await api.setBudgetAmount(month, oldAutoId, 0);
    }
    console.log('\\n  → Zeroed old Auto & Transport (now split)');
  }

  console.log('\\n✅ New category budgets: \$' + totalNew + '/mo added');

  await api.sync();
  await api.shutdown();
}
main();
