const api = require('@actual-app/api');

async function main() {
  await api.init({
    dataDir: '/tmp/actual-data',
    serverURL: 'http://actual-budget:5006',
    password: 'RGR!vwy*hay.vgm0dpg',
  });
  await api.downloadBudget('9b174808-0fe7-4d4d-9b09-7573d3caf074');

  const accounts = await api.getAccounts();
  const categories = await api.getCategories();
  const catByName = {};
  categories.forEach(c => { catByName[c.name] = c.id; });

  const payees = await api.getPayees();
  const payeeMap = {};
  payees.forEach(p => { payeeMap[p.id] = p.name; });

  const gv70Id = catByName['Auto - GV70 Loan'];
  const gv60Id = catByName['Auto - GV60 Loan'];
  const parkingId = catByName['Auto - Parking'];
  const maintId = catByName['Auto - Maintenance'];
  const oldAutoId = catByName['Auto & Transport'];

  let moved = { gv70: 0, gv60: 0, parking: 0, maint: 0 };

  for (const acc of accounts) {
    if (acc.closed) continue;
    const txs = await api.getTransactions(acc.id);

    for (const t of txs) {
      if (t.category !== oldAutoId) continue;

      const payee = (payeeMap[t.payee] || '').toLowerCase();

      if (payee.includes('genesis fi') || payee.includes('gf genesis')) {
        await api.updateTransaction(t.id, { category: gv70Id });
        moved.gv70++;
      } else if (payee.includes('ally') && payee.includes('paymt')) {
        await api.updateTransaction(t.id, { category: gv60Id });
        moved.gv60++;
      } else if (payee.includes('chipay') || payee.includes('parking') || payee.includes('spothero') || payee.includes('laz')) {
        await api.updateTransaction(t.id, { category: parkingId });
        moved.parking++;
      } else if (payee.includes('car wash') || payee.includes('car care')) {
        await api.updateTransaction(t.id, { category: maintId });
        moved.maint++;
      }
    }
  }

  console.log('\\n🚗 Recategorized auto transactions:');
  console.log('  GV70 Loan: ' + moved.gv70);
  console.log('  GV60 Loan: ' + moved.gv60);
  console.log('  Parking:   ' + moved.parking);
  console.log('  Maintenance: ' + moved.maint);

  await api.sync();
  await api.shutdown();
}
main();
" 2>&1 | grep -E "^(🚗|  [A-Z])"
